-- 0004_default_content.sql
-- Default CMS pages and delivery zones. All of it is editable by admins afterwards
-- (Admin → Content, Admin → Delivery). Existing rows are never overwritten.
--
-- ⚠ The legal pages (terms, privacy, returns, vendor agreement) are sensible DRAFTS written for a
--   Kenyan marketplace. Have a qualified Kenyan lawyer review them before launch.

INSERT INTO static_pages (slug, title, body) VALUES
('about', 'About Loom', E'# About Loom\n\nLoom connects you to your community. We are a Kenyan marketplace where independent sellers list their products and customers shop with confidence.\n\n## Why shop on Loom\n\n- **Verified sellers** — every seller is checked before they can sell.\n- **Protected payments** — your money is held safely until you confirm your order arrived.\n- **Pay with M-Pesa** — simple, familiar checkout.\n- **Easy returns** — if something is wrong, we help you sort it out.\n\n## Why sell on Loom\n\nOpen a store in minutes, reach new customers and get paid reliably. See **Sell on Loom** to get started.'),

('contact', 'Contact us', E'# Contact us\n\nWe are here to help.\n\n## Order problems\n\nOpen **My account → Orders**, choose the order and use **Report a problem**. This is the fastest way — your seller and our support team can see everything about the order.\n\n## Anything else\n\nUse the **Help Centre** to find answers, or message us from your account and a support agent will reply.\n\n## Sellers\n\nSellers can reach support from the seller dashboard under **Messages**.'),

('faq', 'Frequently asked questions', E'# Frequently asked questions\n\n## How do I pay?\n\nWe accept M-Pesa. You will receive a payment prompt on your phone at checkout.\n\n## Is my money safe?\n\nYes. When you pay, the money is held by Loom and only released to the seller after you confirm delivery (or after the confirmation period passes with no problem reported).\n\n## When will my order arrive?\n\nDelivery time depends on your location and is shown at checkout.\n\n## Can I cancel an order?\n\nYes, before it has shipped. Go to **My account → Orders** and choose **Cancel order**. You will be refunded to your Loom wallet immediately.\n\n## How do returns work?\n\nIf an item is wrong or damaged, request a return within the return window from **My account → Orders**. If the seller declines and you disagree, you can ask Loom to review.\n\n## What if the seller does not respond?\n\nEvery dispute has a response deadline. If it passes, the case is escalated to our support team automatically.\n\n## Where does my refund go?\n\nRefunds go to your Loom wallet straight away and can be used on your next order, or sent back to M-Pesa where applicable.'),

('terms', 'Terms of use', E'# Terms of use\n\n> **Draft — to be reviewed by legal counsel before launch.**\n\nBy using Loom you agree to these terms.\n\n## 1. Our role\n\nLoom is an online marketplace. Sellers are independent businesses; Loom provides the platform, payment handling and dispute resolution.\n\n## 2. Accounts\n\nYou must give accurate information and keep your password secure. You are responsible for activity on your account.\n\n## 3. Orders and payment\n\nPrices are in Kenyan Shillings and include applicable taxes unless stated. Payment is by M-Pesa. Payment is held by Loom until delivery is confirmed or the confirmation period ends.\n\n## 4. Delivery, returns and refunds\n\nSee the **Return policy**. Disputes are handled under the process described there.\n\n## 5. Prohibited conduct\n\nYou must not sell illegal or counterfeit goods, attempt to take payments outside Loom, share contact details to avoid fees, post fake reviews, or misuse the platform.\n\n## 6. Suspension\n\nWe may suspend accounts that break these terms or put other users at risk.\n\n## 7. Liability\n\nTo the extent permitted by law, Loom is not liable for losses arising from a seller''s goods or conduct beyond the protections described in our policies.\n\n## 8. Governing law\n\nThese terms are governed by the laws of Kenya.\n\n## 9. Changes\n\nWe may update these terms; continued use means you accept the changes.'),

('privacy', 'Privacy policy', E'# Privacy policy\n\n> **Draft — to be reviewed by legal counsel before launch.**\n\nWe respect your privacy and handle personal data in line with the Kenya Data Protection Act, 2019.\n\n## What we collect\n\n- Account details: name, email, phone number.\n- Orders: delivery address, items and payment references.\n- Sellers: business and identity documents for verification.\n- Usage data: pages viewed and device information, to keep the service secure and improve it.\n\n## How we use it\n\nTo process orders and payments, deliver goods, verify sellers, prevent fraud, provide support and send service notifications. We do not sell your personal data.\n\n## Who we share it with\n\nSellers see only what they need to fulfil your order (name, delivery address, phone). Payment, SMS, email and image-hosting providers process data on our behalf.\n\n## Your rights\n\nYou may ask to access, correct or delete your data, and to object to certain processing. Contact us from your account.\n\n## Retention and security\n\nWe keep data only as long as needed for the purposes above and legal obligations, and protect it with technical and organisational safeguards.'),

('returns', 'Return policy', E'# Return policy\n\n> **Draft — to be reviewed by legal counsel before launch.**\n\n## Return window\n\nYou may request a return within **7 days of delivery** if an item is faulty, damaged, not as described or the wrong item.\n\n## How to return\n\n1. Open the order in **My account → Orders** and choose **Request a return**.\n2. Give a reason and add photos if helpful.\n3. The seller approves or declines. If approved, send the item back and add the tracking number.\n4. When the seller confirms receipt, your refund is approved by Loom finance and paid out.\n\n## Disagreements\n\nIf the seller declines, you can **escalate to Loom**. Our support team reviews the evidence from both sides and decides: full refund, partial refund, release to seller, or replacement.\n\n## Refunds\n\nRefunds go to your Loom wallet or back to M-Pesa. Delivery fees are refunded when the fault is the seller''s.\n\n## Not returnable\n\nItems the law or the listing states are not returnable (for example perishables or personalised goods).'),

('vendor-agreement', 'Vendor agreement', E'# Vendor agreement\n\n> **Draft — to be reviewed by legal counsel before launch.**\n\nThis agreement applies to every seller on Loom.\n\n## 1. Eligibility and verification\n\nYou must complete identity and business verification and keep your information accurate.\n\n## 2. Listings\n\nList only genuine goods you are entitled to sell, with accurate descriptions, prices and stock. Listings may be reviewed before they go live.\n\n## 3. Fees\n\nLoom charges a commission on the value of items sold. The rate applying to you is shown in your dashboard and may vary by category.\n\n## 4. Orders and delivery\n\nYou must ship paid orders promptly, add a tracking number, and mark delivery. Ship only paid orders.\n\n## 5. Payment and payouts\n\nCustomer payments are held in escrow and become available to you after the customer confirms delivery, or automatically after the confirmation period if there is no dispute. Payouts follow the payout schedule you choose, above the minimum amount. Loom may hold payouts during an investigation.\n\n## 6. Returns, refunds and disputes\n\nYou must respond to returns and disputes within the stated deadlines. Refunds ordered under the dispute process are deducted from your balance.\n\n## 7. Prohibited conduct\n\nNo counterfeit or illegal goods; no taking customers or payments off the platform; no sharing of contact details to avoid fees; no fake reviews.\n\n## 8. Suspension and termination\n\nLoom may suspend or close stores that breach this agreement.\n\n## 9. Governing law\n\nKenyan law governs this agreement.'),

('sell-on-loom', 'Sell on Loom', E'# Sell on Loom\n\nReach customers across Kenya with your own online store.\n\n## How it works\n\n1. **Create your account** and complete your seller profile.\n2. **Verify your business** with a few documents.\n3. **Open your store** and list your products.\n4. **Sell and ship.** We handle secure M-Pesa payments.\n5. **Get paid** on your chosen schedule, weekly or monthly.\n\n## What you get\n\n- A store page with your logo and banner\n- Order, stock and earnings dashboards\n- Protected payments and a fair dispute process\n- Coupons and promotions to grow sales\n\nReady? **Create a seller account** from the Sell on Loom link in the menu.'),

('help', 'Help Centre', E'# Help Centre\n\n## Shopping\n\n- **Placing an order** — add items to your cart, choose delivery, and pay with M-Pesa.\n- **Tracking an order** — **My account → Orders** shows every step and the courier tracking number.\n- **Confirming delivery** — once your order arrives, confirm it so the seller is paid. If you do nothing, payment is released automatically after the confirmation period.\n\n## Problems\n\n- **Wrong or damaged item** — request a return within 7 days.\n- **Item never arrived** — open a dispute from the order page; payment stays protected while we investigate.\n- **Payment taken but order unpaid** — wait a few minutes, then check your M-Pesa messages and contact support with the receipt number.\n\n## Your wallet\n\nRefunds can be credited to your Loom wallet. Wallet balance is applied at checkout.\n\n## Selling\n\n- **Getting verified** — upload the requested documents; most reviews finish within a few working days.\n- **Payouts** — see **Payouts** in your dashboard for balances, history and statements.\n- **Disputes and returns** — respond before the deadline to protect your account.\n\nStill stuck? Visit **Contact us**.')
ON CONFLICT (slug) DO NOTHING;

-- Default delivery zones (adjust prices in Admin → Delivery to match your couriers)
INSERT INTO shipping_zones (name, counties, base_fee, per_kg_fee, free_over, est_days_min, est_days_max)
SELECT * FROM (VALUES
  ('Nairobi metro',  ARRAY['Nairobi','Kiambu','Machakos','Kajiado'], 250::numeric, 40::numeric, 5000::numeric, 1, 2),
  ('Major towns',    ARRAY['Mombasa','Kisumu','Nakuru','Eldoret','Thika','Nyeri','Meru','Kisii','Malindi','Naivasha'], 400::numeric, 60::numeric, 8000::numeric, 2, 4),
  ('Rest of Kenya',  ARRAY['Kakamega','Bungoma','Embu','Garissa','Kericho','Kitale','Kitui','Lamu','Machakos','Nanyuki','Narok','Voi'], 600::numeric, 80::numeric, 12000::numeric, 3, 7)
) AS v(name, counties, base_fee, per_kg_fee, free_over, est_days_min, est_days_max)
WHERE NOT EXISTS (SELECT 1 FROM shipping_zones);
